// World 8 "Xưởng Phép Thuật" (curriculum.md §6.3, §6.3.1, ADR-0023): spells ("phép thuật") and
// spells with a box. These tests pin what the levels teach: what each lesson demo does, the
// predict answers, the one real fix of each bughunt, that every spell runs at least twice, the
// boss order trap, that each new block is introduced with its tooltip, and the copy rules.
// The content is generated by tools/content-gen/w08/gen.ts (🟨 nháp, chờ HLV chơi thử).
import { readFileSync } from 'node:fs';
import {
  LessonSchema,
  LevelSchema,
  WorldSchema,
  type LessonCard,
  type Level,
  type WorkspaceJson,
} from '@codequest/content-schema';
import { runLevel, type RunOutcome } from '@codequest/engine';
import { getGameKind, resolveLevelConfigs, robotlabRulesSchema } from '@codequest/games';
import { countWords } from '@codequest/validator';
import { describe, expect, it } from 'vitest';

const CONTENT = new URL('../../../content/', import.meta.url);
const W08 = new URL('worlds/w08-xuong-phep-thuat/', CONTENT);
const read = (path: string, base = W08): unknown =>
  JSON.parse(readFileSync(new URL(path, base), 'utf8'));

const shared = { robotlab: robotlabRulesSchema.parse(read('shared/robotlab.json', CONTENT)) };
const world = WorldSchema.parse(read('world.json'));
const lessons = new Map(
  world.lessonIds.map((id) => [id, LessonSchema.parse(read(`lessons/${id}.json`))] as const),
);
const levels = new Map(
  world.levelIds.map((id) => [id, LevelSchema.parse(read(`levels/${id}.json`))] as const),
);
const levelById = (id: string): Level => {
  const level = levels.get(id);
  if (level === undefined) throw new Error(`no level ${id}`);
  return level;
};
const lessonById = (id: string) => {
  const lesson = lessons.get(id);
  if (lesson === undefined) throw new Error(`no lesson ${id}`);
  return lesson;
};

function run(level: Level, workspace: WorkspaceJson, mode: Level['mode'] = 'build'): RunOutcome {
  const kind = getGameKind(level.kind);
  if (kind === undefined) throw new Error(`no kind ${level.kind}`);
  const resolved = resolveLevelConfigs({ ...level, mode, maxBlocks: undefined }, shared);
  return runLevel({ kind, level: resolved, workspace });
}
function program(workspace: WorkspaceJson | undefined): WorkspaceJson {
  if (workspace === undefined) throw new Error('missing program');
  return workspace;
}
const solved = (id: string): RunOutcome => run(levelById(id), program(levelById(id).solution));
const given = (id: string): RunOutcome =>
  run(levelById(id), program(levelById(id).initialWorkspace));
const seconds = (o: RunOutcome): number =>
  Math.max(0, ...o.events.map((e) => (e as { t?: number }).t ?? 0));

/** How many times each spell ran (`call` events). */
function casts(o: RunOutcome): Map<string, number> {
  const out = new Map<string, number>();
  for (const e of o.events as ReadonlyArray<{ type: string; id?: string }>) {
    if (e.type === 'call' && e.id !== undefined) out.set(e.id, (out.get(e.id) ?? 0) + 1);
  }
  return out;
}

/** Runs a lesson demo card as a one-map level. */
function runDemo(card: LessonCard): RunOutcome {
  if (card.type !== 'demo') throw new Error('not a demo');
  const level = LevelSchema.parse({
    id: 'demo',
    worldId: world.id,
    stage: 'practice',
    kind: card.kind,
    mode: 'build',
    title: 'demo',
    objective: 'demo',
    learningGoal: 'demo',
    toolbox: [],
    hints: [],
    par: 1,
    config: card.config,
    ...(card.procedures === undefined ? {} : { procedures: card.procedures }),
    solution: card.workspace,
  });
  return run(level, card.workspace);
}
const demos = (id: string): LessonCard[] =>
  lessonById(id).cards.filter((card) => card.type === 'demo');

describe('W8 world', () => {
  it('has 20 levels + creative, 6 lessons, the scene and the story props', () => {
    expect(world.levelIds).toHaveLength(21);
    expect(world.lessonIds).toHaveLength(6);
    expect(world.theme.scene).toBe('xuong-phep-thuat');
    const props = (world.chapters ?? []).map((c) => c.art.prop);
    expect(props).toContain('spellbook');
    expect(props).toContain('wand');
  });

  it('keeps one loop deep and declares a dạy phép cap per spell type', () => {
    for (const level of levels.values()) {
      if (level.mode === 'creative') continue;
      expect(level.maxLoopDepth, level.id).toBe(1);
      // Parsons pieces are fixed; the cap only matters where the toolbox has dạy phép.
      if (level.mode === 'predict' || level.mode === 'parsons') continue;
      const procs = level.procedures ?? [];
      const plain = procs.filter((p) => p.param === undefined).length;
      const boxed = procs.length - plain;
      if (plain > 0) expect(level.maxInstances?.['cq_proc_def'], level.id).toBe(plain);
      if (boxed > 0) expect(level.maxInstances?.['cq_proc_def_n'], level.id).toBe(boxed);
    }
  });
});

describe('W8 solutions', () => {
  const built = [...levels.values()].filter(
    (l) => l.solution !== undefined && l.mode !== 'creative',
  );

  it.each(built.map((l) => l.id))('%s: the solution wins and every spell runs ≥ 2 times', (id) => {
    const outcome = solved(id);
    expect(outcome.result).toBe('success');
    const ran = casts(outcome);
    for (const proc of levelById(id).procedures ?? []) {
      expect(ran.get(proc.id) ?? 0, `${id} ${proc.id}`).toBeGreaterThanOrEqual(2);
    }
  });

  it('l08: the spell in a loop is needed (no-loop version is over the cap)', () => {
    const level = levelById('w08-l08');
    expect(level.par).toBe(11);
    expect(level.maxBlocks).toBe(11);
    expect(casts(solved('w08-l08')).get('hop')).toBe(4);
  });

  it('l11: one question spell wins on all 3 maps', () => {
    expect(levelById('w08-l11').variants).toHaveLength(2);
  });
});

describe('W8 predict answers', () => {
  const answer = (id: string): string | undefined =>
    run(levelById(id), program(levelById(id).initialWorkspace), 'predict').answerKey;
  it.each([
    ['w08-l02', 'stop@3,3'],
    ['w08-l07', 'win'],
    ['w08-l14', 'stop@3,3'],
    ['w08-l19', 'stop@5,7'],
  ])('%s → %s, and a wrong card is the flag', (id, key) => {
    expect(answer(id)).toBe(key);
    const keys = levelById(id).predict?.options.map((o) => o.key) ?? [];
    expect(keys).toContain(key);
    if (id !== 'w08-l07') expect(keys).toContain('win');
  });
});

/** A hint that fires on run-end with `reason` (directly or inside `all`). */
function hintFor(level: Level, reason: string): string[] {
  type Cond = { lastReason?: string; all?: Cond[] };
  const has = (cond: Cond): boolean =>
    cond.lastReason === reason || (cond.all ?? []).some((c) => has(c));
  return level.hints.filter((h) => has(h.when as Cond)).map((h) => h.id);
}

/** Main program of one workspace with the spells of another (bughunt one-fix variants). */
function mixed(main: WorkspaceJson, spells: WorkspaceJson): WorkspaceJson {
  const [start] = main.blocks.blocks;
  if (start === undefined) throw new Error('empty workspace');
  return { blocks: { languageVersion: 0, blocks: [start, ...spells.blocks.blocks.slice(1)] } };
}

describe('W8 bughunts', () => {
  it.each([
    ['w08-l05', 'HIT_WALL'],
    ['w08-l10', 'OFF_LINE'],
    ['w08-l16', 'NOTHING_TO_GRAB'],
    ['w08-l18', 'NOTHING_TO_GRAB'],
  ])('%s: the given program loses with %s, and a hint answers that reason', (id, reason) => {
    const outcome = given(id);
    expect(outcome.result).not.toBe('success');
    expect(outcome.reasonCode).toBe(reason);
    expect(hintFor(levelById(id), reason).length).toBeGreaterThan(0);
  });

  it('l18: each half-fixed program fails with its own reason and its own hint', () => {
    const level = levelById('w08-l18');
    const start = program(level.initialWorkspace);
    const end = program(level.solution);
    const bodyFixed = run(level, mixed(start, end));
    const numberFixed = run(level, mixed(end, start));
    expect(bodyFixed.reasonCode).toBe('OFF_LINE');
    expect(hintFor(level, 'OFF_LINE')).toEqual(['off']);
    expect(numberFixed.reasonCode).toBe('NOTHING_TO_GRAB');
    expect(hintFor(level, 'NOTHING_TO_GRAB')).toEqual(['grab']);
  });
});

describe('W8 boss', () => {
  it('wins in 65 s of 70 and keeps 2 grab blocks', () => {
    const level = levelById('w08-boss');
    const outcome = solved('w08-boss');
    expect(outcome.result).toBe('success');
    expect(seconds(outcome)).toBe(65);
    expect((level.config as { rules?: { timeLimit?: number } }).rules?.timeLimit).toBe(70);
    expect(level.maxInstances?.['robot_grab']).toBe(2);
    expect(level.parUnproven).toBe(true);
  });

  it('the grab-cap hints fire only when the cap is really used up', () => {
    for (const id of ['w08-l12', 'w08-boss']) {
      const hint = levelById(id).hints.find((h) => h.id === 'grab');
      expect(JSON.stringify(hint?.when), id).toContain('"instancesFull":"robot_grab"');
    }
  });
});

describe('W8 lessons', () => {
  it('opening lesson: teaching alone does nothing, casting walks to the flag', () => {
    const [teach, cast] = demos('w08-lesson');
    if (teach === undefined || cast === undefined) throw new Error('missing demos');
    expect(runDemo(teach).result).toBe('incomplete');
    expect(runDemo(cast).result).toBe('success');
  });
  it('sửa phép: the wrong spell crashes at the first cast, the fixed one wins', () => {
    const [bug, fixed] = demos('w08-lesson-sua-phep');
    if (bug === undefined || fixed === undefined) throw new Error('missing demos');
    const crash = runDemo(bug);
    expect(crash.reasonCode).toBe('HIT_WALL');
    expect(casts(crash).get('stair')).toBe(1);
    expect(runDemo(fixed).result).toBe('success');
  });
  it('hai phép: the right names win, a swapped name crashes', () => {
    const [right, swapped] = demos('w08-lesson-hai-phep');
    if (right === undefined || swapped === undefined) throw new Error('missing demos');
    expect(runDemo(right).result).toBe('success');
    expect(runDemo(swapped).reasonCode).toBe('HIT_WALL');
  });
  it.each(['w08-lesson-phep-trong-lap', 'w08-lesson-phep-hoi', 'w08-lesson-hop-cua-phep'])(
    '%s: every demo wins',
    (id) => {
      for (const card of demos(id)) expect(runDemo(card).result).toBe('success');
    },
  );
});

describe('W8 copy', () => {
  const TOOLTIP: Readonly<Record<string, string>> = {
    cq_proc_def: 'Dạy phép: nhớ các lệnh bên trong, chưa làm ngay',
    cq_proc_call: 'Làm phép: làm hết lệnh trong phép, rồi làm tiếp',
    cq_proc_def_n: 'Dạy phép với hộp: làm phép thì hộp nhận số',
    cq_proc_call_n: 'Làm phép với số: hộp của phép nhận số này',
  };
  it.each([
    ['w08-l01', 'cq_proc_def'],
    ['w08-l01', 'cq_proc_call'],
    ['w08-l13', 'cq_proc_def_n'],
    ['w08-l13', 'cq_proc_call_n'],
  ])('%s introduces %s with "Khối mới! " + its tooltip', (id, type) => {
    const hint = levelById(id).hints.find((h) => h.point === `block:${type}`);
    expect(hint?.say).toBe(`Khối mới! ${TOOLTIP[type] ?? ''}`);
  });

  /** Every text the child sees: levels, lesson cards, chapters. */
  const childTexts = (): Array<[string, string]> => [
    ...[...levels.values()].flatMap((level) =>
      [
        level.title,
        level.objective,
        level.mission ?? '',
        level.thinkingHint ?? '',
        ...level.hints.map((h) => h.say),
        ...(level.predict?.options.map((o) => o.label) ?? []),
      ].map((text): [string, string] => [level.id, text]),
    ),
    ...[...lessons.values()].flatMap((lesson) =>
      lesson.cards
        .flatMap((card) => [
          card.text,
          ...(card.type === 'quiz' ? [...card.options, card.explain] : []),
        ])
        .map((text): [string, string] => [lesson.id, text]),
    ),
    ...(world.chapters ?? []).flatMap((chapter) =>
      [chapter.title, ...chapter.lines].map((text): [string, string] => [chapter.id, text]),
    ),
    ['world', world.story],
  ];

  it('says "khối" to the child; "lệnh" only inside a quoted tooltip', () => {
    const tooltips = Object.values(TOOLTIP);
    for (const [where, text] of childTexts()) {
      if (tooltips.some((t) => text.includes(t))) continue;
      expect(text, where).not.toMatch(/(^|\s)lệnh/);
    }
  });

  it('writes counts as digits (ordinals and "ngã ba" are words)', () => {
    const word = /(^|[\s,.!?:;(])(hai|ba|bốn|năm|sáu|bảy|tám|chín|mười)(?=[\s,.!?:;)]|$)/i;
    for (const [where, text] of childTexts()) {
      expect(text.replace(/ngã ba|thứ \p{L}+/giu, ''), where).not.toMatch(word);
    }
  });

  it('robot missions name the cube kind and colour', () => {
    for (const level of levels.values()) {
      if (level.kind !== 'robotlab' || level.mode === 'creative') continue;
      expect(level.mission, level.id).toMatch(/khối (trung hòa|ô nhiễm)/);
      expect(level.mission, level.id).toMatch(/đỏ|vàng|xanh lá/);
    }
  });

  it('hints that are not block intros or rules are questions', () => {
    const statements = new Set(['def', 'call', 'defn', 'calln', 'rule', 'names', 'loose', 'free']);
    for (const level of levels.values()) {
      for (const hint of level.hints) {
        if (statements.has(hint.id)) continue;
        expect(hint.say.trim().endsWith('?'), `${level.id} ${hint.id}: ${hint.say}`).toBe(true);
      }
    }
  });

  it('thinking hints are questions', () => {
    for (const level of levels.values()) {
      if (level.mode === 'creative') continue;
      expect(level.thinkingHint?.trim().endsWith('?'), level.id).toBe(true);
    }
  });

  it('lesson cards stay within 12 words', () => {
    for (const lesson of lessons.values()) {
      for (const card of lesson.cards) {
        if (card.type === 'quiz') continue;
        expect(countWords(card.text), `${lesson.id}: ${card.text}`).toBeLessThanOrEqual(12);
      }
    }
  });
});
